import{_ as s,a0 as a,w as p,s as l,ao as d,I as i,x as e,a1 as n,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何使用安卓设备控制你的Linux PC | LCTT x X-CMD","titleTemplate":false,"description":"如何使用安卓设备控制你的Linux PC | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用安卓设备控制你的Linux PC | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用安卓设备控制你的Linux PC | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to Control Your Linux PC with an Android Device","title":"如何使用安卓设备控制你的Linux PC","tag":"201311","desc":""},"relativePath":"201311/How to Control Your Linux PC with an Android Device.md","filePath":"[post].md"}'),u={name:"201311/How to Control Your Linux PC with an Android Device.md"};function h(m,t,x,C,S,c){const o=a("Link");return p(),l("div",null,[t[11]||(t[11]=d(`<h1 id="如何使用安卓设备控制你的linux-pc" tabindex="-1">如何使用安卓设备控制你的Linux PC <a class="header-anchor" href="#如何使用安卓设备控制你的linux-pc" aria-label="Permalink to “如何使用安卓设备控制你的Linux PC”">​</a></h1><p><strong>下面的教程会指导所有的Linux用户如何在系统上安装SSH，以便通过安卓智能手机远程访问他们的电脑。</strong></p><p><img src="http://i1-news.softpedia-static.com/images/news2/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004-2.jpg" alt=""> 如今我们所有人都拥有一台平板或触屏手机，我们经常使用它们在深夜里看电影或电视节目，听歌或者读一本好书。你可以把本文称作是“懒人教程”，它是专门为那些在大晚上因为太过疲惫而懒得去开启他们电脑上的某些应用程序，移动、删除，复制或重命名某些文件，甚至懒得去关掉PC的人准备的。</p><p>的确，已经有各种各样的远程桌面解决方案，但是许多方案费用很高，或者实现效果很糟糕，无法像预期一样运行，迫使你最终还是得去电脑上做你原本想做的事情。</p><p>在这个教程里面，我们将使用一种简单、安全、高效的协议，它被称为SSH (Secure Shell)，很容易从默认的软件仓库中安装（在Arch linx中是openssh，在Ubuntu中是openssh-server）。</p><h3 id="配置ssh服务器" tabindex="-1">配置SSH服务器 <a class="header-anchor" href="#配置ssh服务器" aria-label="Permalink to “配置SSH服务器”">​</a></h3><p>在安装完成后，你需要为SSH服务器进行基本配置。为此，你需要使用文本编辑器编辑/etc/ssh/sshd_config这个文件。</p><p>1.在文件尾部添加下面一行（下面的yourusername使用你的Linux机器上存在的用户名代替）</p><p>AllowUsers yourusername</p><p>2.取消&quot;#PermitRootLogin&quot;这行注释，把&quot;no&quot;替换成&quot;yes&quot;（译注：下面的选项修改和是否允许ssh登录无关，只是允许root直接登录，一般而言，并不建议如下这样的远程root直接登录。）：</p><pre><code>PermitRootLogin no
</code></pre><p>3.为了安全起见，你需要修改SSH 连接默认的22端口到一个更大编号的端口，譬如在我们的例子中是55441 （但不要使用55441，这是我举个列子，可以找另一个四位或者五位数字）。因此，取消注释并编辑&quot;#Port 22&quot;如下（译注：你可以选择任何一个大于1024并小于65535的端口，只要他没有被别的程序占用，为什么不试试你的幸运数字呢？）：</p><pre><code>   Port 55441
</code></pre><h3 id="开启ssh服务器" tabindex="-1">开启SSH服务器### <a class="header-anchor" href="#开启ssh服务器" aria-label="Permalink to “开启SSH服务器###”">​</a></h3><p>在Ubuntu上，SSH服务通过下面的命令启动：</p><pre><code>sudo /etc/init.d/ssh start
</code></pre><p>当你每次修改上述配置文件时，都需要通过下面的命令重启：</p><pre><code>sudo /etc/init.d/ssh restart
</code></pre><p>在Arch Linux上，你可以使用下面的命令启动SSH服务：</p><pre><code>sudo systemctl start sshd
</code></pre><h3 id="配置安卓设备上的ssh客户端" tabindex="-1">配置安卓设备上的SSH客户端### <a class="header-anchor" href="#配置安卓设备上的ssh客户端" aria-label="Permalink to “配置安卓设备上的SSH客户端###”">​</a></h3><p>JuiceSSH似乎是安卓上最好的SSH客户端之一，而且是免费的。同时，如果你认为它的功能比较简单，可以花费少量的钱来得到更多高级的特性，譬如亚马逊 AWS/EC2 集成，团队协作，以及更多其它的特性。</p><p>一旦软件安装完毕，开启它，然后你会要求输入一个加密的密码以保证连接的安全。这个密码由AES-256进行加密，因此除非你的设备被偷，否则没有人能够获取它们。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_001.jpg" alt=""></p><p>现在，添加一个新连接，为你的电脑选择名称、IP地址，上面设定的端口号以及一个需要被创建的身份。</p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_002.jpg" alt=""></p><p><img src="http://i1-news.softpedia-static.com/images/extra/LINUX/large/sshlinuxandroid-large_003.jpg" alt=""></p><p>这就是我的Arch Linux机器，这是通过我的安卓平板上的JuiceSSH客户端访问到的界面。如果在这个教程中你遇到问题，请在下面进行评论。</p><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://news.softpedia.com/news/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004.shtml"},{default:r(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/How-to-Control-Your-Linux-PC-with-an-Android-Device-396004.shtml",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=e("译者：",-1)),n(o,{href:"https://github.com/KayGuoWhu"},{default:r(()=>[...t[2]||(t[2]=[e("KayGuoWhu",-1)])]),_:1}),t[5]||(t[5]=e(" 校对：",-1)),n(o,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...t[3]||(t[3]=[e("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原创翻译，",-1)),n(o,{href:"http://linux.cn/"},{default:r(()=>[...t[7]||(t[7]=[e("Linux中国",-1)])]),_:1}),t[10]||(t[10]=e(" 荣誉推出",-1))])])}const P=s(u,[["render",h]]);export{f as __pageData,P as default};
